const sheetData = $json.values;
if (!sheetData || sheetData.length < 2) return [];
const headers = sheetData[0];
const results = [];
for (let i = 1; i < sheetData.length; i++) {
  const row = sheetData[i];
  if (!row || row.length === 0) continue;
  const obj = {};
  headers.forEach((header, idx) => { obj[header] = row[idx] !== undefined ? row[idx] : ''; });
  results.push({ json: obj });
}
return results;

const MAPA_EMAILS = {
  'Rodrigo Bertolini': 'rodrigo.bertolini@fazcapital.com.br',
  'Lucas Boeira':      'lucas.boeira@fazcapital.com.br',
  'Allini Pianca':     'allini.pianca@fazcapital.com.br',
  'Athos Baruk':       'athos.baruk@fazcapital.com.br',
  'Fabio Borges':      'fabio.borges@fazcapital.com.br'
};

// Adicione novos nomes conforme necessario
const GENEROS = {
  'rodrigo': 'M', 'lucas': 'M', 'athos': 'M', 'fabio': 'M',
  'allini': 'F', 'ana': 'F', 'maria': 'F', 'patricia': 'F'
};

function findEmail(nome) {
  if (!nome) return '';
  if (MAPA_EMAILS[nome]) return MAPA_EMAILS[nome];
  const nomeLower = nome.toLowerCase();
  for (const [chave, email] of Object.entries(MAPA_EMAILS)) {
    const chaveLower = chave.toLowerCase();
    if (chaveLower.includes(nomeLower)) return email;
    if (chave.split(' ').some(p => p.toLowerCase() === nomeLower)) return email;
  }
  // Fallback: busca pelo primeiro nome (ex: 'Allini Boeira' -> bate com 'Allini Pianca')
  const primeiroInput = nomeLower.split(' ')[0];
  if (primeiroInput) {
    for (const [chave, email] of Object.entries(MAPA_EMAILS)) {
      if (chave.split(' ')[0].toLowerCase() === primeiroInput) return email;
    }
  }
  return '';
}

function norm(s) {
  return (s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
}

const d = $json;
const threadId  = (d['ID da thread'] || d['Thread ID'] || '').trim();
const status    = (d['Status'] || '').trim();
const ultStatus = (d['Último Status Enviado'] || d['Ultimo Status Enviado'] || '').trim();
const sNorm     = norm(status);
const uNorm     = norm(ultStatus);

if (!threadId) { return []; }
if (sNorm === '' || sNorm === 'aberto') { return []; }
if (sNorm === uNorm) { return []; }

const responsavelRaw = (d['Responsável'] || d['Responsavel'] || '').split('|')[0].trim();

// Estrategia 1: extrai email diretamente do campo (formato Telegram: first_name=email)
const emailNoCampo = (responsavelRaw.match(/([\w.+-]+@[\w.-]+\.[\w]+)/) || [])[1] || '';

// Estrategia 2 (fallback): lookup pelo nome no mapa
const nomeSemEmail = responsavelRaw.replace(/[\w.+-]+@[\w.-]+\.[\w]+/g, '').trim();

const emailDest = emailNoCampo || findEmail(nomeSemEmail);
if (!emailDest) { return []; }

// Saudacao com genero a partir do primeiro nome
const primeiroNome = nomeSemEmail.split(' ')[0] || '';
const genero = GENEROS[primeiroNome.toLowerCase()] || 'M';
const saudacao = (genero === 'F' ? 'Prezada' : 'Prezado') + (primeiroNome ? ' ' + primeiroNome : '');

const prompt =
  'Você é assistente de comunicação da FAZ Capital e está redigindo um e-mail de atualização de caso para um colega da mesma área.\n\n' +
  'Abaixo está uma nota de status interna. Transforme-a em um parágrafo para incluir no e-mail.\n\n' +
  'REGRAS PRINCIPAIS:\n' +
  '1. Texto FORA das aspas = é uma informação ou fala MINHA (de quem escreve o e-mail).\n' +
  '   → Escreva de forma direta e afirmativa em primeira pessoa, sem adicionar "recebi o retorno de que" ou qualquer introdução extra.\n' +
  '   → Exemplo: nota "O caso está com o time responsável" → e-mail: "O caso está com o time responsável."\n\n' +
  '2. Texto ENTRE aspas (" ") = é um retorno recebido da área responsável.\n' +
  '   → Integre como "recebi o retorno de que..." ou "o retorno foi que...", reescrevendo de forma profissional.\n' +
  '   → Exemplo: nota "\"Conforme analisado, a tarifa é devida\"" → e-mail: "Recebi o retorno de que, conforme analisado, a tarifa é devida."\n\n' +
  '3. Se a nota misturar texto fora e dentro das aspas, una-os naturalmente em um único parágrafo.\n\n' +
  'OUTRAS REGRAS:\n' +
  '- Use linguagem direta e menos formal — é para um colega da mesma área\n' +
  '- Mantenha datas, horários e valores originais sem inventar nada\n' +
  '- NÃO inclua saudação, assinatura, título ou qualquer outro elemento além do parágrafo\n' +
  '- Escreva apenas UM parágrafo, sem listas ou marcadores\n\n' +
  'Nota de status: "' + status + '"';

return [{
  json: {
    ...d,
    thread_id_ref: threadId,
    email_destinatario: emailDest,
    saudacao: saudacao,
    openai_body: {
      model: 'gpt-4o-mini',
      max_tokens: 400,
      messages: [{ role: 'user', content: prompt }]
    }
  }
}];

const textoAI = (
  $json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content
) || '';

if (!textoAI) {
  console.log('AVISO: IA nao retornou texto:', JSON.stringify($json));
  return [];
}

const d         = $('PREPARAR_PROMPT_IA').item.json;
const idCaso    = d['ID Caso']        || '';
const cliente   = d['Código Cliente'] || d['Codigo_Cliente'] || '';
const assunto   = d['Assunto']         || '';
const protoBV   = d['Protocolo BV']    || '';
const threadId  = d['thread_id_ref']  || '';
const emailDest = d['email_destinatario'] || '';
const saudacao  = d['saudacao'] || 'Prezado(a)';

if (!emailDest || !threadId) {
  console.log('SKIP: emailDest ou threadId ausente');
  return [];
}

const corpo =
  saudacao + ',\n\n' +
  textoAI + '\n\n' +
  'Protocolo BV: ' + protoBV + '\n\n\n' +
  'Atenciosamente,';

console.log('OK: e-mail montado para', emailDest, '| saudacao:', saudacao);

return [{
  json: {
    ...d,
    corpo_email: corpo,
    id_caso: idCaso,
    status_atual: (d['Status'] || '').trim(),
    email_destinatario: emailDest
  }
}];

const msgs = $json.value;
if (!msgs || msgs.length === 0) {
  console.log('AVISO: Email original nao encontrado para thread:', $('Montar Corpo do E-mail').item.json.thread_id_ref);
  return [];
}

const originalId = msgs[0].id;
const d          = $('Montar Corpo do E-mail').item.json;

console.log('Email original encontrado:', originalId);

return [{
  json: {
    original_message_id: originalId,
    id_caso:    d.id_caso    || d['ID Caso'] || '',
    status_atual: d.status_atual || '',
    reply_body: {
      message: {
        body: { contentType: 'Text', content: d.corpo_email },
        toRecipients: [{ emailAddress: { address: d.email_destinatario } }],
        ccRecipients:  [{ emailAddress: { address: 'lucas.boeira@fazcapital.com.br' } }]
      }
    }
  }
}];

function addBusinessDays(days) {
  const date = new Date();
  let added = 0;
  while (added < days) {
    date.setDate(date.getDate() + 1);
    const dow = date.getDay();
    if (dow !== 0 && dow !== 6) added++;
  }
  return date;
}

const d        = $('Preparar Envio Resposta').item.json;
